window.OLAYLAR = [
{ t:"1299-01", k:"kurulus", etiket:["siyaset"], b:"Osmanlı Beyliği'nin kuruluşu", gun:"1299 (gelenekselleşmiş tarih)", yer:"Söğüt / Bilecik", kisiler:"Osman Gazi",
  d:"Kayı boyundan Osman Gazi'nin Söğüt-Domaniç çevresinde bağımsız hareket etmeye başlaması, Osmanlı Devleti'nin kuruluşu için gelenekselleşmiş başlangıç kabul edilir; kimi tarihçiler 1302 Bapheus zaferini gerçek dönüm noktası sayar. Beylik, Bizans uç bölgesindeki konumu sayesinde gaza akınlarıyla hızla güç topladı. Selçuklu mirasının çözüldüğü bu ortamda Osman Gazi çevresine ahiler, gaziler ve göçer Türkmenleri topladı; Şeyh Edebali ile kurduğu bağ, beyliğin manevi meşruiyetinin temeli sayılır. Aynı tarihte haritaya katılan diğer yerleşimler: İnegöl, Yarhisar.", kaynak:"osman-i" },
{ t:"1326-04-06", k:"fetih", etiket:["toprak-kazanc","kultur-sanat","bilim"], b:"Bursa'nın fethi", gun:"6 Nisan 1326", yer:"Bursa", yer_id:"Bursa", kisiler:"Orhan Gazi, Osman Gazi",
  d:"Yıllarca abluka altında tutulan Bursa, kuşatmanın son aşamasını yöneten Orhan Gazi'ye teslim oldu; şehir beyliğin ilk büyük başkenti yapıldı. Fetih haberinin, ölüm döşeğindeki Osman Gazi'ye ulaştırıldığı rivayet edilir; Osman Gazi vasiyeti üzerine Bursa'ya defnedildi. Şehir kısa sürede cami, imaret ve medreselerle donatılarak erken Osmanlı şehirciliğinin modeli hâline geldi.", kaynak:"bursa", duygu:["🎉"] },
{ t:"1331-03-02", k:"fetih", etiket:["toprak-kazanc","kultur-sanat","bilim"], b:"İznik'in fethi", gun:"2 Mart 1331", yer:"İznik", yer_id:"İznik", kisiler:"Orhan Gazi",
  d:"Bizans'ın Anadolu'daki en önemli merkezlerinden İznik (Nikaia), 1329 Pelekanon zaferinin ardından direnme umudunu yitirerek Orhan Gazi'ye teslim oldu. İlk Osmanlı medresesi burada kuruldu ve Dâvûd-i Kayserî gibi âlimler ders vermeye başladı; şehir erken dönemin ilim merkezi oldu. Ayasofya Kilisesi camiye çevrilerek fetih geleneğinin erken bir örneği sergilendi.", kaynak:"iznik", duygu:["🎉"] },
{ t:"1337-01-01", k:"fetih", etiket:["toprak-kazanc"], b:"İzmit'in fethi", gun:"1337", yer:"İzmit", yer_id:"İzmit", kisiler:"Orhan Gazi",
  d:"İzmit'in (Nikomedia) düşmesiyle Bizans'ın Anadolu yakasındaki son önemli kalesi de Osmanlı yönetimine girdi; İstanbul'un karşı kıyısına kadar bütün Kocaeli yarımadası Osmanlı toprağı oldu. Böylece beylik, Marmara'nın güney ve doğu kıyılarının tamamına hâkim olarak Rumeli'ye geçişin altyapısını hazırladı.", kaynak:"izmit", duygu:["🎉"] },
{ t:"1352-03-01", k:"fetih", etiket:["toprak-kazanc"], b:"Çimpe Kalesi — Rumeli'ye geçiş", gun:"1352 (Gelibolu'nun fethi 1354)", yer:"Gelibolu yarımadası", kisiler:"Süleyman Paşa, Orhan Gazi",
  d:"Orhan Gazi'nin oğlu Süleyman Paşa, Bizans iç savaşında verilen Çimpe Kalesi'ni 1352'de üs edinmiş; Mart 1354'te Gelibolu'yu yıkan büyük deprem sonrasında boşalan kaleler hızla tahkim edilerek yarımada kalıcı Osmanlı köprübaşına dönüştürülmüştü. Anadolu'dan getirilen Türkmen nüfusun iskânıyla desteklenen bu adım, Osmanlıların Avrupa kıtasındaki 550 yılı aşacak varlığının başlangıcıdır.", kaynak:"cimpe-kalesi", duygu:["🎉"] },
{ t:"1362-03", k:"taht", etiket:["siyaset","toprak-kazanc","ekonomi"], b:"I. Murad tahta çıktı", gun:"Mart 1362", yer:"Bursa", yer_id:"Bursa", kisiler:"I. Murad",
  d:"Orhan Gazi'nin ölümüyle tahta geçen I. Murad (Hüdavendigâr), 27 yıllık saltanatında devleti bir uç beyliğinden imparatorluk iskeletine taşıdı. Pençik sistemiyle Yeniçeri Ocağı'nın temeli atıldı, tımar düzeni yaygınlaştırıldı, Rumeli Beylerbeyliği kuruldu ve vezirlik kurumu güçlendirildi. Balkan fetihleri onun döneminde sistemli bir devlet siyaseti hâline geldi.", kaynak:"murad-i" },
{ t:"1361-03-01", k:"fetih", etiket:["toprak-kazanc"], b:"Edirne'nin fethi", gun:"1361 (TDV'nin ağırlık verdiği görüş; 1362/1367/1369 de öne sürülmüştür)", yer:"Edirne", yer_id:"Edirne", kisiler:"I. Murad, Lala Şâhin Paşa",
  d:"Trakya'nın kilit şehri Edirne'nin (Adrianopolis) alınması, Balkan fetihlerinin ana üssünü ve yönünü belirledi; fetih tarihi kaynaklarda 1361 ile 1369 arasında tartışmalıdır. Şehir kısa süre sonra başkent yapılarak devletin ağırlık merkezinin Rumeli'ye kaydığını ilan etti; İstanbul'un fethine kadar yaklaşık 90 yıl payitaht kaldı.", kaynak:"edirne", duygu:["🎉"] },
{ t:"1389-06", k:"savas", etiket:["savas","ittifak"], b:"I. Kosova Savaşı — I. Murad'ın şehadeti", gun:"15 Haziran 1389", yer:"Kosova Ovası", kisiler:"I. Murad, Yıldırım Bayezid, Knez Lazar, Miloš Obilić",
  d:"Knez Lazar önderliğindeki Balkan ittifakı Kosova Ovası'nda kesin yenilgiye uğratıldı; Sırbistan Osmanlı yüksek hâkimiyetine girdi. Savaş alanını gezen I. Murad, Sırp asilzadesi Miloš Obilić tarafından hançerlenerek şehit edildi — savaş meydanında ölen tek Osmanlı padişahıdır. Yerine ordugâhta Yıldırım Bayezid geçirildi; kardeşi Yakub Çelebi boğduruldu ve bu, kardeş katli uygulamasının bilinen ilk örneklerinden oldu.", kaynak:"kosova-savaslari" },
{ t:"1396-09", k:"savas", etiket:["savas","toprak-kazanc"], b:"Niğbolu Zaferi", gun:"25 Eylül 1396", yer:"Niğbolu, Tuna kıyısı", kisiler:"Yıldırım Bayezid, Kral Sigismund",
  d:"Macar kralı Sigismund'un çağrısıyla toplanan ve Fransız-Burgonya şövalyelerinin de katıldığı büyük Haçlı ordusu, Tuna kıyısındaki Niğbolu önünde Yıldırım Bayezid tarafından ağır bozguna uğratıldı. Zafer, Bulgaristan üzerindeki Osmanlı hâkimiyetini kesinleştirdi ve Bayezid'e halifeden 'Sultân-ı iklîm-i Rûm' unvanını kazandırdı; Avrupa'da bir kuşak boyunca büyük Haçlı seferi düzenlenemedi.", kaynak:"nigbolu-savasi" },
{ t:"1402-07-28", k:"savas", etiket:["savas","toprak-kazanc"], b:"Ankara Savaşı — Fetret Devri başladı", gun:"28 Temmuz 1402", yer:"Çubuk Ovası, Ankara", kisiler:"Yıldırım Bayezid, Timur",
  d:"Timur'un ordusu karşısında Çubuk Ovası'nda alınan ağır yenilgide Yıldırım Bayezid esir düştü ve birkaç ay sonra esarette öldü. Timur, Anadolu beyliklerini yeniden diriltti; Osmanlı toprakları Bayezid'in oğulları arasında parçalandı ve 11 yıl sürecek taht mücadelesi (Fetret Devri) başladı. Devletin kuruluşundan beri yaşadığı en ağır kriz olan bu dönem, merkeziyetçi yapının önemini Osmanlı hafızasına kazıdı. Aynı tarihte elden çıkan diğer yerleşimler: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Aydos Kalesi, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, İmralı Adası, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delçev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofya, Niş, Vidin, Tırnova, Varna, Şumnu, Silistre, Niğbolu, Rusçuk, Selanik, Serez, Kavala, Üsküp, Manastır, Ohri, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia).", kaynak:"ankara-savasi", duygu:["⚔️"] },
{ t:"1413-07", k:"taht", etiket:["siyaset","antlasma","toprak-kazanc"], b:"Çelebi Mehmed birliği yeniden kurdu", gun:"5 Temmuz 1413", yer:"Çamurlu, Sofya yakını", kisiler:"I. Mehmed, Mûsâ Çelebi",
  d:"Kardeşler arasındaki son hesaplaşmada Mûsâ Çelebi'yi Çamurlu'da yenen I. Mehmed, ülke topraklarını tek yönetim altında birleştirdi; bu yüzden 'devletin ikinci kurucusu' sayılır. Saltanatında yıpranan devlet yapısı onarıldı, Anadolu beylikleriyle ilişkiler dengelendi ve Rumeli'de temkinli bir barış siyaseti izlendi.", kaynak:"mehmed-i" },
{ t:"1416-05", k:"isyan", etiket:["ayaklanma","kultur-sanat"], b:"Şeyh Bedreddin isyanı", gun:"1416", yer:"Karaburun, Deliorman, Serez", kisiler:"Şeyh Bedreddin, Börklüce Mustafa, Torlak Kemal",
  d:"Fetret Devri'nde kazaskerlik yapmış büyük fakih ve mutasavvıf Şeyh Bedreddin'in çevresinde gelişen dinî-toplumsal hareket, Karaburun'da Börklüce Mustafa ve Manisa'da Torlak Kemal'in ayaklanmalarıyla eş zamanlı patlak verdi. İsyanlar kanlı biçimde bastırıldı; Bedreddin, Deliorman'da yakalanarak Serez'de idam edildi. Olay, Osmanlı tarihindeki en erken büyük toplumsal-mehdici ayaklanma olarak edebiyat ve tarih yazımında derin iz bıraktı.", kaynak:"bedreddin-simavi" },
{ t:"1444-11", k:"savas", etiket:["savas","antlasma"], b:"Varna Zaferi", gun:"10 Kasım 1444", yer:"Varna, Karadeniz kıyısı", kisiler:"II. Murad, Kral III. Ladislas, Hunyadi Yanoş",
  d:"Szeged antlaşmasını bozarak güneye inen Macar-Leh Haçlı ordusu, tahttan çekilmişken ordunun başına dönen II. Murad tarafından Varna'da imha edildi; genç kral III. Ladislas savaş alanında öldü. Zafer, Balkanlar'daki Osmanlı varlığını tasfiye etmeye yönelik son büyük dış müdahale şansını ortadan kaldırdı ve İstanbul'un fethine giden yolu güvenceye aldı.", kaynak:"varna-savasi" },
{ t:"1448-10", k:"savas", etiket:["savas"], b:"II. Kosova Savaşı", gun:"17–20 Ekim 1448", yer:"Kosova Ovası", kisiler:"II. Murad, Hunyadi Yanoş",
  d:"Varna'nın intikamını almak isteyen Hunyadi Yanoş'un ordusu, üç gün süren çetin muharebede II. Murad tarafından kesin yenilgiye uğratıldı. Bu, Haçlıların Balkanlar'da Osmanlı'ya karşı giriştiği son büyük meydan savaşıdır; zaferle Tuna'nın güneyindeki Osmanlı hâkimiyeti artık geri döndürülemez biçimde yerleşti.", kaynak:"kosova-savaslari" },
{ t:"1453-05-29", k:"fetih", etiket:["toprak-kazanc","kultur-sanat","ekonomi"], b:"İstanbul'un Fethi", gun:"29 Mayıs 1453", yer:"İstanbul", yer_id:"İstanbul", kisiler:"II. Mehmed (Fatih), XI. Konstantinos, Ulubatlı Hasan (rivayet)",
  d:"53 gün süren kuşatmanın ardından 29 Mayıs sabahı surları aşan Osmanlı ordusu şehre girdi; son imparator XI. Konstantinos çarpışmalarda öldü ve 1100 yıllık Doğu Roma İmparatorluğu tarihe karıştı. Genç padişah 'Fâtih' unvanını aldı, şehri başkent yaparak Ayasofya'yı camiye çevirdi; şehir kısa sürede iskân ve imarla yeniden canlandırıldı. Dev topların döktürülmesi, gemilerin karadan yürütülmesi ve surların önündeki kuşatma düzeni, dönemin askerî mühendisliğinin zirvesi kabul edilir. Fetih, Avrupa tarih yazımında Orta Çağ'ın bitişinin sembol tarihlerinden sayılır.", kaynak:"istanbulun-fethi", duygu:["🎉"] },
{ t:"1461-08-15", k:"fetih", etiket:["toprak-kazanc","ekonomi"], b:"Trabzon'un fethi", gun:"15 Ağustos 1461", yer:"Trabzon", yer_id:"Trabzon", kisiler:"Fatih Sultan Mehmed, David Komnenos",
  d:"Fatih'in ordu ve donanmayla eş zamanlı yürüttüğü zorlu Karadeniz seferi sonunda Trabzon Rum İmparatorluğu teslim oldu; Bizans dünyasının Anadolu'daki bu son kalıntısının tasfiyesiyle Karadeniz'in güney kıyısı bütünüyle Osmanlı hâkimiyetine girdi. Komnenos hanedanına son verilmesi, Fatih'in 'iki denizin ve iki karanın hükümdarı' iddiasını pekiştirdi. Aynı tarihte haritaya katılan diğer yerleşimler: Giresun, Rize.", kaynak:"trabzon", duygu:["🎉"] },
{ t:"1473-08-11", k:"savas", etiket:["savas","ittifak"], b:"Otlukbeli Savaşı", gun:"11 Ağustos 1473", yer:"Otlukbeli, Erzincan yakını", kisiler:"Fatih Sultan Mehmed, Uzun Hasan",
  d:"Doğu'da büyük bir güç hâline gelen ve Venedik'le ittifak kuran Akkoyunlu hükümdarı Uzun Hasan, Otlukbeli'nde Fatih'in ateşli silahlarla donanmış ordusu karşısında ağır yenilgiye uğradı. Zafer, Anadolu'da Osmanlı üstünlüğünü kesinleştirdi; klasik ordu karşısında top ve tüfek kullanan merkezî ordunun üstünlüğünün de erken bir kanıtı oldu.", kaynak:"otlukbeli-savasi", duygu:["⚔️"] },
{ t:"1473-01-01", k:"fetih", etiket:["toprak-kazanc"], b:"Silifke'nin kesin fethi — Karamanoğulları'nın son direnişinin kırılması", gun:"1473, Otlukbeli sonrası (TDV ay/gün vermiyor)", yer:"Silifke, İçel", kisiler:"Fatih Sultan Mehmed, Gedik Ahmed Paşa, Kasım Bey", d:"Silifke Kalesi 1472'de bir kez Gedik Ahmed Paşa'ya teslim olmuş, ama aynı yıl Karamanoğlu Kasım Bey, Akdeniz'deki Haçlı donanmasının yardımıyla kaleyi geri almıştı. Otlukbeli zaferinin ardından Fatih, oğlunu ve Gedik Ahmed Paşa'yı bölgeyi kesin olarak ele geçirmekle görevlendirdi; eski Osmanlı topçularının yardımıyla barut deposu ateşlenip kale hızla düşürüldü. Böylece Karamanoğulları'nın Taşeli-İçel dağlarındaki son direnişi kırıldı; beyliğin tasfiyesi 1474'te tamamlanacaktı.", kaynak:"silifke", duygu:["🎉"] },
{ t:"1475-06-06", k:"fetih", etiket:["toprak-kazanc"], b:"Kırım'ın Osmanlı himayesine girişi", gun:"6 Haziran 1475", yer:"Kefe, Kırım", kisiler:"Gedik Ahmed Paşa, Mengli Giray",
  d:"Gedik Ahmed Paşa komutasındaki donanma, Ceneviz'in elindeki Kefe başta olmak üzere Kırım'ın güney kıyı şehirlerini fethetti; bu kıyılar doğrudan Osmanlı sancağı yapıldı. Kırım Hanlığı ise Mengli Giray ile Osmanlı yüksek hâkimiyetini tanıyan imtiyazlı bir bağlı devlet hâline geldi ve üç asır boyunca kuzey siyasetinin temel taşı oldu; Karadeniz artık fiilen bir Osmanlı iç denizine dönüştü. Aynı tarihte haritaya katılan diğer yerleşimler: Bahçesaray, Kerç, Azak.", kaynak:"kirim", duygu:["🎉"] },
{ t:"1481-05", k:"taht", etiket:["siyaset","ekonomi","diplomasi"], b:"Fatih'in ölümü — Cem Sultan olayı", gun:"3 Mayıs 1481 (Fatih'in vefatı)", yer:"Gebze / Bursa / Rodos", kisiler:"II. Bayezid, Cem Sultan",
  d:"Fatih'in sefer yolunda ani ölümü üzerine tahta II. Bayezid geçti; kardeşi Cem Sultan saltanat iddiasıyla Bursa'da adına hutbe okutup para bastırdı. Yenilince önce Memlûklere, sonra Rodos şövalyelerine sığındı; şövalyelerin ve papalığın elinde Avrupa diplomasisinin pazarlık kozuna dönüşen Cem, 1495'te Napoli'de öldü. Bu olay, Osmanlı dış siyasetini on beş yıl boyunca temkinli davranmaya zorladı.", kaynak:"cem-sultan" },
{ t:"1514-08", k:"savas", etiket:["savas","toprak-kazanc"], b:"Çaldıran Zaferi", gun:"23 Ağustos 1514", yer:"Çaldıran Ovası, Van'ın kuzeydoğusu", kisiler:"Yavuz Sultan Selim, Şah İsmail",
  d:"Anadolu'da Safevî propagandasının yarattığı tehdidi kökünden çözmek isteyen Yavuz Sultan Selim, Şah İsmail'in ordusunu Çaldıran Ovası'nda top ve tüfek üstünlüğüyle ağır yenilgiye uğrattı. Tebriz'e girildi; Doğu ve Güneydoğu Anadolu ile Musul-Diyarbakır hattı Osmanlı yönetimine katıldı. İdrîs-i Bitlisî'nin gayretiyle Kürt beylerinin Osmanlı'ya bağlanması, doğu sınırının asırlarca sürecek çerçevesini kurdu.", kaynak:"caldiran-savasi" },
{ t:"1516-08", k:"savas", etiket:["savas"], b:"Mercidabık Zaferi", gun:"24 Ağustos 1516", yer:"Mercidabık, Halep'in kuzeyi", kisiler:"Yavuz Sultan Selim, Kansu Gavri",
  d:"Memlûk ordusu Halep'in kuzeyindeki Mercidabık'ta birkaç saat içinde dağıtıldı; yaşlı sultan Kansu Gavri savaş sırasında öldü. Halep ve Şam kapılarını ardına kadar açan zaferle Suriye, Lübnan ve Filistin Osmanlı yönetimine geçti; Memlûk Devleti'nin sonunu getirecek Mısır seferinin yolu açıldı.", kaynak:"mercidabik-muharebesi" },
{ t:"1517-01-22", k:"fetih", etiket:["toprak-kazanc","ekonomi"], b:"Ridaniye — Mısır'ın fethi ve hilâfet", gun:"22 Ocak 1517", yer:"Ridaniye, Kahire önü", kisiler:"Yavuz Sultan Selim, Tomanbay",
  d:"Sina çölünü hızla aşan Osmanlı ordusu, Tomanbay'ın savunma hattını Ridaniye'de yararak Kahire'ye girdi; direnişi süren Tomanbay yakalanarak idam edildi ve Memlûk Devleti tarihe karıştı. Mısır, Hicaz ve kutsal şehirler Osmanlı yönetimine girdi; Abbasî halifesi ve kutsal emanetler İstanbul'a götürüldü. Hilâfetin Osmanlı hanedanına geçişiyle padişahlar İslam dünyasının önderliği iddiasını üstlendi; Baharat Yolu'nun denetimi de imparatorluğa büyük gelir sağladı. Aynı tarihte haritaya katılan diğer yerleşimler: Akkâ, Maan, Sayda, Kerak.", kaynak:"ridaniye-savasi", duygu:["🎉"] },
{ t:"1520-09-30", k:"taht", etiket:["siyaset","kultur-sanat","ekonomi"], b:"Kanunî Sultan Süleyman tahta çıktı", gun:"30 Eylül 1520", yer:"İstanbul", yer_id:"İstanbul", kisiler:"I. Süleyman (Kanunî)",
  d:"Yavuz'un ölümü üzerine tek erkek evlât olarak tahta geçen I. Süleyman'ın 46 yıllık saltanatı, imparatorluğun siyasî, askerî, hukukî ve kültürel zirvesi kabul edilir. Örfî hukuku sistemleştiren kanunnâmeleri ona 'Kanunî' unvanını kazandırdı; Batı'da 'Muhteşem' (Magnificent) diye anıldı. Mimar Sinan'ın eserleri, divan edebiyatının altın çağı ve donanmanın Akdeniz üstünlüğü bu dönemin simgeleridir.", kaynak:"suleyman-i", duygu:["👑"] },
{ t:"1521-08-29", k:"fetih", etiket:["toprak-kazanc"], b:"Belgrad'ın fethi", gun:"29 Ağustos 1521", yer:"Belgrad", yer_id:"Belgrad", kisiler:"Kanunî Sultan Süleyman",
  d:"Fatih'in 1456'da alamadığı ve 'Orta Avrupa'nın kilidi' sayılan Belgrad, Kanunî'nin ilk seferinde Tuna-Sava kavşağındaki kuşatmayla düştü. Macaristan'ın güney savunma hattı çökmüş oldu; beş yıl sonra Mohaç'a, yirmi yıl sonra Budin'in ilhakına uzanan Orta Avrupa harekâtının kapısı bu fetihle açıldı.", kaynak:"belgrad", duygu:["🎉"] },
{ t:"1522-12-21", k:"fetih", etiket:["toprak-kazanc"], b:"Rodos'un fethi", gun:"21 Aralık 1522", yer:"Rodos adası", kisiler:"Kanunî Sultan Süleyman, Üstâd-ı Âzam Villiers de l'Isle-Adam",
  d:"Doğu Akdeniz deniz yollarını ve hac güzergâhını tehdit eden Saint Jean şövalyelerinin üssü Rodos, aylar süren kanlı kuşatmanın ardından vire ile teslim oldu; şövalyelerin adadan serbestçe ayrılmasına izin verildi (sonradan Malta'ya yerleştiler). Anadolu kıyılarının güvenliği sağlandı ve İstanbul-Mısır deniz hattı kesintisiz Osmanlı denetimine girdi.", kaynak:"rodos", duygu:["🎉"] },
{ t:"1526-08-29", k:"savas", etiket:["savas"], b:"Mohaç Meydan Muharebesi", gun:"29 Ağustos 1526", yer:"Mohaç Ovası, Macaristan", kisiler:"Kanunî Sultan Süleyman, Kral II. Layoş",
  d:"Macar ordusu, Mohaç Ovası'nda yaklaşık iki saat içinde top ateşi ve manevra üstünlüğüyle yok edildi; Kral II. Layoş kaçarken bataklıkta öldü. Osmanlı tarihinin en hızlı kazanılmış büyük meydan savaşlarından olan Mohaç, bağımsız Macar krallığını fiilen sona erdirdi ve Orta Avrupa'da Osmanlı-Habsburg rekabeti çağını açtı.", kaynak:"mohac-muharebesi", duygu:["⚔️"] },
{ t:"1529-09", k:"savas", etiket:["savas","ekonomi"], b:"I. Viyana Kuşatması", gun:"27 Eylül – 16 Ekim 1529", yer:"Viyana", yer_id:"Viyana", kisiler:"Kanunî Sultan Süleyman, Ferdinand",
  d:"Habsburgların Macar tahtına el atmasına karşı düzenlenen seferde Osmanlı ordusu Viyana'yı kuşattı; ağır topların yolda bırakılması, erken bastıran kış ve iaşe güçlüğü yüzünden üç hafta sonra kuşatma kaldırıldı. Şehir alınamadıysa da Macaristan üzerindeki Osmanlı nüfuzu korundu; Viyana önleri, imparatorluğun Orta Avrupa'daki lojistik erişim sınırını işaret etti.", kaynak:"viyana" },
// hatalar 5.docx madde 3 — SİLİNDİ (1533-04): mükerrer: olaylar_ek7.js 1534-04-06 kaydı TDV'nin verdiği tam günü (6 Nisan 1534) taşıyor
{ t:"1534-12-04", k:"fetih", etiket:["toprak-kazanc"], b:"Bağdat'ın fethi — Irakeyn Seferi", gun:"Aralık 1534 başı", yer:"Tebriz ve Bağdat", kisiler:"Kanunî Sultan Süleyman, Pargalı İbrahim Paşa",
  d:"'İki Irak' (Irak-ı Arap ve Irak-ı Acem) üzerine düzenlenen seferde önce Tebriz'e, ardından savaşsız biçimde Bağdat'a girildi; Abbasîlerin eski başkentinin alınması Osmanlı hükümdarına İslam dünyasında büyük itibar kazandırdı. İmâm-ı Âzam Ebû Hanîfe'nin türbesi ihya edildi; Bağdat ve Basra'nın katılmasıyla Osmanlı toprakları Basra Körfezi'ne ulaştı. Aynı tarihte haritaya katılan diğer yerleşimler: Kerkük, Kerbelâ.", kaynak:"irakeyn-seferi", duygu:["🎉"] },
{ t:"1538-09", k:"savas", etiket:["savas"], b:"Preveze Deniz Zaferi", gun:"27–28 Eylül 1538", yer:"Preveze açıkları, Adriyatik girişi", kisiler:"Barbaros Hayreddin Paşa, Andrea Doria",
  d:"Papa'nın öncülüğünde kurulan Haçlı donanması, sayıca üstün olmasına rağmen Barbaros'un rüzgârı ve kıyıyı ustaca kullanan taktiğiyle Preveze açıklarında dağıtıldı; Andrea Doria muharebe alanını terk etti. Zafer, Akdeniz'de yaklaşık 33 yıl sürecek tartışmasız Osmanlı deniz üstünlüğünü kurdu; Türk denizcilik geleneğinde donanma gününün simge tarihidir. Aynı tarihte haritaya katılan diğer yerleşimler: Aden, Bender.", kaynak:"preveze-deniz-savasi" },
{ t:"1541-08-29", k:"fetih", etiket:["toprak-kazanc"], b:"Budin'in ilhakı — Macaristan Osmanlı eyaleti", gun:"29 Ağustos 1541", yer:"Budin (Budapeşte)", kisiler:"Kanunî Sultan Süleyman",
  d:"Habsburgların Budin'i kuşatması üzerine sefere çıkan Kanunî, şehri kurtardıktan sonra Orta Macaristan'ı doğrudan Osmanlı yönetimine alarak Budin Beylerbeyliği'ni kurdu; Erdel ise Osmanlı'ya bağlı özerk bir prenslik yapıldı. Macaristan'ın bu üçe bölünmüş düzeni yaklaşık 150 yıl sürdü ve Osmanlı'nın Orta Avrupa'daki kalıcı yönetim iskeletini oluşturdu.", statu_dogrudan:["Budin","Peşte"], kaynak:"budin", duygu:["🎉"] },
{ t:"1555-05-29", k:"antlasma", etiket:["antlasma","diplomasi"], b:"Amasya Antlaşması", gun:"29 Mayıs 1555", yer:"Amasya", yer_id:"Amasya", kisiler:"Kanunî Sultan Süleyman, Şah Tahmasb",
  d:"Yıllarca süren Osmanlı-Safevî savaşlarını bitiren ilk resmî barış antlaşmasıdır. Bağdat ve Irak Osmanlı'da kaldı, Doğu Anadolu sınırı ilk kez karşılıklı tanındı; Safevîler Osmanlı ülkesindeki Şiî propagandasını durdurmayı, Osmanlılar da İranlı hacıların geçiş güvenliğini üstlendi. Antlaşma, iki devlet arasındaki ilişkilerin hukukî çerçevesinin ilk örneği oldu.", kaynak:"amasya-antlasmasi", duygu:["🤝"] },
{ t:"1566-09-07", k:"taht", etiket:["siyaset"], b:"Zigetvar — Kanunî'nin vefatı", gun:"7 Eylül 1566", yer:"Zigetvar, Macaristan", kisiler:"Kanunî Sultan Süleyman, Sokullu Mehmed Paşa, Zrinyi",
  d:"72 yaşındaki Kanunî, on üçüncü seferinde kuşattığı Zigetvar Kalesi'nin düşmesinden birkaç saat önce otağında vefat etti; Sokullu Mehmed Paşa, ordunun dağılmaması için ölümü haftalarca gizledi. Kale alındı, ancak devlet en uzun saltanatlı ve en görkemli padişahını kaybetmişti; tahta oğlu II. Selim geçti ve devlet yönetiminde büyük vezirlerin ağırlığı artmaya başladı.", kaynak:"zigetvar", vefat_id:"suleyman1", duygu:["👑"] },
{ t:"1571-08", k:"fetih", etiket:["toprak-kazanc","ittifak","ekonomi"], b:"Kıbrıs'ın fethi", gun:"1 Ağustos 1571 (Magosa'nın teslimi)", yer:"Kıbrıs", kisiler:"Lala Mustafa Paşa, Marcantonio Bragadin",
  d:"Venedik yönetimindeki Kıbrıs'a 1570'te çıkarma yapıldı; Lefkoşa hızla düştü, Magosa ise ancak on bir aylık kuşatmadan sonra Ağustos 1571'de teslim oldu. Doğu Akdeniz ticaret ve hac yollarının güvenliği açısından kritik olan ada, bir beylerbeylik olarak örgütlendi ve Anadolu'dan nüfus iskân edildi; fetih, İnebahtı'ya varacak büyük Haçlı ittifakının da gerekçesi oldu.", kaynak:"kibris" },
{ t:"1571-10", k:"savas", etiket:["savas"], b:"İnebahtı (Lepanto) yenilgisi", gun:"7 Ekim 1571", yer:"İnebahtı körfezi, Yunanistan", kisiler:"Müezzinzâde Ali Paşa, Don Juan, Uluç Ali Reis",
  d:"Kıbrıs'ın fethi üzerine birleşen Haçlı donanması, Osmanlı donanmasını İnebahtı körfezinde yakalayarak büyük bölümünü imha etti; kaptan-ı deryâ Müezzinzâde Ali Paşa şehit düştü, yalnızca Uluç Ali'nin filosu kurtuldu. Sokullu'nun 'donanmanın kaybı sakalın tıraşıdır, daha gür çıkar' sözüyle anılan felaketin ardından donanma bir kışta yeniden inşa edildi; ne var ki Akdeniz'deki mutlak üstünlük psikolojik olarak sarsılmıştı.", kaynak:"inebahti-deniz-savasi" },
{ t:"1596-10", k:"savas", etiket:["savas"], b:"Haçova Meydan Muharebesi", gun:"26 Ekim 1596", yer:"Haçova (Mezőkeresztes), Macaristan", kisiler:"III. Mehmed, Hoca Sâdeddin Efendi, Arşidük Maximilian",
  d:"Uzun Savaş'ın (1593–1606) en büyük meydan muharebesinde, III. Mehmed'in bizzat başında bulunduğu ordu, dağılma noktasına geldiği anda Hoca Sâdeddin Efendi'nin telkiniyle toparlanarak Habsburg ordusunu bozguna uğrattı. Osmanlıların kazandığı son büyük klasik meydan savaşı kabul edilir; ancak savaşın genel gidişini değiştirmemesi, askerî sistemdeki yıpranmanın da işareti sayıldı.", kaynak:"hacova-meydan-savasi" },
{ t:"1606-11-11", k:"antlasma", etiket:["antlasma","diplomasi","toprak-kazanc","ekonomi"], b:"Zitvatorok Antlaşması", gun:"11 Kasım 1606", yer:"Zsitva suyu ağzı, Macaristan", kisiler:"I. Ahmed, II. Rudolf",
  d:"On üç yıllık yıpratıcı savaşı bitiren antlaşmayla Habsburg hükümdarı ilk kez 'Roma İmparatoru' sıfatıyla padişahın dengi sayıldı ve yıllık haraç kaldırıldı. Toprak kaybı yok denecek kadar azdı; ama diplomatik dilin bu değişimi, Osmanlı'nın Avrupa karşısındaki mutlak üstünlük iddiasının sona erdiğinin sembolü olarak okunur.", kaynak:"zitvatorok-antlasmasi", duygu:["🤝"] },
{ t:"1622-05", k:"isyan", etiket:["ayaklanma","kultur-sanat"], b:"II. Osman'ın katli (Hâile-i Osmâniye)", gun:"20 Mayıs 1622", yer:"İstanbul, Yedikule", kisiler:"II. Osman (Genç), Kara Davud Paşa",
  d:"Hotin seferinde yeniçerilerin isteksizliğini gören Genç Osman'ın orduyu ıslah etme ve başkenti taşıma tasarıları, kapıkulu ocaklarını ayaklandırdı. Padişah tahttan indirilip Yedikule zindanında boğduruldu; Osmanlı tarihinde ilk kez bir padişah, kulları eliyle katledilmiş oldu. 'Hâile-i Osmâniye' (Osman faciası) diye anılan olay, saray-ocak dengesini kalıcı biçimde bozdu ve yüzyıl boyunca sürecek meşruiyet tartışmalarını başlattı.", kaynak:"osman-ii" },
// hatalar 5.docx madde 8 — gün ZATEN biliniyordu (gun:"17 Mayıs 1639" ve
// ANTLASMALAR kaydı 1639-05-17) ama t: ay hassasiyetindeydi; CLAUDE.md §8'e göre
// ay hassasiyetli tarih ayın 1'ine genişler ve gün hassasiyetli toprak
// değişimlerinden ÖNCE sıralanır. Tam güne çekildi.
{ t:"1639-05-17", k:"antlasma", etiket:["antlasma","diplomasi"], b:"Kasr-ı Şirin Antlaşması", gun:"17 Mayıs 1639", yer:"Kasr-ı Şirin", kisiler:"IV. Murad, Kemankeş Kara Mustafa Paşa, Şah Safi",
  d:"IV. Murad'ın Bağdat'ı geri almasının (1638) ardından imzalanan antlaşma, yüz yılı aşkın Osmanlı-Safevî savaşlarına son verdi. Bağdat ve Irak kesin olarak Osmanlı'da kaldı, Revan Safevîlere bırakıldı; çizilen hat, küçük değişikliklerle bugünkü Türkiye-İran sınırının temeli oldu ve dünyanın en uzun ömürlü sınırlarından biri sayılır.", kaynak:"kasr-i-sirin-antlasmasi", duygu:["🤝"] },
// hatalar 5.docx madde 3 — SİLİNDİ (1656-09): mükerrer: olaylar_ek7.js 1656-09-15 kaydı tam günü ve şartlı kabul ayrıntısını taşıyor
{ t:"1669-09-27", k:"fetih", etiket:["toprak-kazanc","antlasma"], b:"Girit'in fethi tamamlandı", gun:"Eylül 1669 (Kandiye'nin teslimi)", yer:"Kandiye, Girit", kisiler:"Fâzıl Ahmed Paşa, Francesco Morosini",
  d:"1645'te başlayan Girit savaşının son perdesi olan Kandiye kuşatması, Fâzıl Ahmed Paşa'nın üç yıllık kararlı harekâtıyla sonuçlandı; Venedik komutanı Morosini şehri antlaşmayla teslim etti. Yaklaşık çeyrek asır süren mücadele Osmanlı tarihinin en uzun kuşatması olarak kayda geçti; Doğu Akdeniz'in son büyük Latin kalesi de Osmanlı yönetimine girdi. Adanın kuzey kıyısındaki üç küçük kayalık kale — Suda, Spinalonga ve Granbosa — henüz Venedik'te kaldı; bunlar ayrı adacıklar üzerinde kurulu olduğu için haritada Girit'in geri kalanından ayrı gösterilemez.", kaynak:"girit", duygu:["🎉"] },
{ t:"1692-01-01", k:"fetih", etiket:["toprak-kazanc"], b:"Granbosa Kalesi'nin fethi — Girit'in Venedik'te kalan kayalık kalelerinden biri", gun:"1692 (TDV yalnız yılı veriyor)", yer:"Granbosa (Gramvousa), Girit", kisiler:"", d:"1669'da Kandiye'nin teslimiyle Girit'in fethi büyük ölçüde tamamlanmış sayılsa da, adanın kuzeybatı ucundaki kayalık ada-kale Granbosa yirmi üç yıl daha Venedik elinde kaldı. 1692'de ele geçirilmesiyle Girit'teki üç Venedik kalıntısından biri temizlendi; Suda ve Spinalonga ise 1715 Mora seferini bekleyecekti.", kaynak:"girit", duygu:["🎉"] },
{ t:"1715-01-01", k:"fetih", etiket:["toprak-kazanc"], b:"Suda ve Spinalonga kalelerinin fethi — Girit'te son Venedik izinin silinmesi", gun:"1715, Mora seferi sırasında (TDV yalnız yılı veriyor)", yer:"Suda, Spinalonga, Girit", kisiler:"", d:"Granbosa'nın 1692'de düşmesinden yirmi üç yıl sonra, Mora seferinin bir yan koluyla Venedik'in Girit'teki son iki dayanağı olan Suda ve Spinalonga kaleleri de fethedildi. Böylece 1645'te başlayan Girit fethi, kırk altı yılın sonunda adanın son santimetresine kadar tamamlanmış oldu.", kaynak:"girit", duygu:["🎉"] },
{ t:"1672-10-18", k:"antlasma", etiket:["antlasma","diplomasi","toprak-kazanc","ekonomi"], b:"Bucaş Antlaşması — en geniş sınırlar", gun:"18 Ekim 1672", yer:"Bucaş, Podolya", kisiler:"IV. Mehmed, Fâzıl Ahmed Paşa",
  d:"Lehistan seferinde Kamaniçe'nin fethinin ardından imzalanan Bucaş Antlaşması'yla Podolya Osmanlı'ya katıldı ve Ukrayna'nın bir bölümü himaye altına alındı. İmparatorluk böylece Avrupa'daki en geniş sınırlarına ulaştı; bu nokta, genişleme çağının zirvesi ve aynı zamanda son halkası kabul edilir.", kaynak:"bucas-antlasmasi", duygu:["🤝"] },
{ t:"1683-09", k:"savas", etiket:["savas","ittifak"], b:"II. Viyana Kuşatması bozgunu", gun:"12 Eylül 1683", yer:"Viyana", yer_id:"Viyana", kisiler:"Merzifonlu Kara Mustafa Paşa, Jan Sobieski",
  d:"Merzifonlu Kara Mustafa Paşa'nın iki ay süren Viyana kuşatması, Lehistan kralı Jan Sobieski'nin Kahlenberg tepelerinden indirdiği ani darbeyle bozguna döndü; ordu ağırlıklarını bırakarak çekildi, Merzifonlu Belgrad'da idam edildi. Zaferin ardından kurulan Kutsal İttifak'la savaş 16 yıl sürdü; Osmanlı tarihinde büyük gerilemenin başlangıç anı olarak bu bozgun gösterilir.", kaynak:"merzifonlu-kara-mustafa-pasa" },
{ t:"1699-01-26", k:"antlasma", etiket:["antlasma","diplomasi","ittifak","toprak-kazanc","toprak-kaybi","ekonomi"], b:"Karlofça Antlaşması — ilk büyük toprak kaybı", gun:"26 Ocak 1699", yer:"Karlofça, Sırbistan", kisiler:"II. Mustafa, Amcazâde Hüseyin Paşa, Rami Mehmed Efendi",
  d:"On altı yıllık Kutsal İttifak savaşlarını bitiren Karlofça'yla Macaristan ve Erdel Avusturya'ya, Podolya Lehistan'a, Mora ve Dalmaçya kıyıları Venedik'e bırakıldı. Osmanlı tarihinde ilk kez bu ölçekte toprak, masa başında ve kalıcı olarak elden çıkıyordu; antlaşma, imparatorluğun Avrupa karşısında savunmaya geçtiği yeni çağın başlangıç belgesi sayılır ve Osmanlı diplomasi tarihinin de dönüm noktasıdır.", kaynak:"karlofca", duygu:["🤝","😔"] },
{ t:"1711-07-19", k:"savas", etiket:["savas","antlasma"], b:"Prut Zaferi", gun:"21 Temmuz 1711", yer:"Prut nehri kıyısı, Boğdan", kisiler:"Baltacı Mehmed Paşa, Çar I. Petro",
  d:"Poltava yenilgisinden sonra Osmanlı'ya sığınan İsveç kralı meselesi yüzünden çıkan savaşta, Çar I. Petro'nun ordusu Prut kıyısında kuşatılarak teslim olmak zorunda kaldı. İmzalanan antlaşmayla Azak geri alındı; ordunun imha edilmemesi ve çarın serbest bırakılması ise o günden bugüne tartışılan bir karar olarak tarihe geçti.", kaynak:"prut-antlasmasi", duygu:["⚔️"] },
// MÜKERRER SİLİNDİ (2026-07-30): Pasarofça Antlaşması burada ve
// olaylar_ek5.js:462'de İKİ KEZ yazılmıştı — aynı gün, aynı k:"antlasma",
// aynı kaynak slug, 6 ortak kişi. Oturum 2'nin yeni mükerrer kademesi yakaladı.
// Zengin olan (Petrovaradin, Banat, Küçük Eflak, ticaret ahidnâmesi) ek5'teki
// kayıttı; buradaki maddenin TEK farkı Lâle Devri kültür içeriğiydi (matbaa,
// tercüme heyetleri, çiçek aşısı) ve o içerik ek5'e taşındı. Silmeden önce
// taşındı — mükerrer temizliğinde kayıp veri en sinsi hatadır.
{ t:"1730-09-25", k:"isyan", etiket:["ayaklanma","kultur-sanat","ekonomi"], b:"Patrona Halil İsyanı", gun:"28 Eylül 1730", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Patrona Halil, III. Ahmed, Nevşehirli Damad İbrahim Paşa",
  d:"İran cephesindeki başarısızlık, vergiler ve saray çevresinin lüksüne duyulan öfke, hamam tellâğı Patrona Halil'in önderliğinde büyük bir ayaklanmaya dönüştü. Sadrazam İbrahim Paşa öldürüldü, III. Ahmed tahttan indirildi ve Lâle Devri sona erdi; isyancıların aylarca şehre hükmetmesi, merkezî otoritenin kırılganlığını çarpıcı biçimde gösterdi.", kaynak:"patrona-isyani", duygu:["✊"] },
{ t:"1739-09-18", k:"antlasma", etiket:["antlasma","diplomasi","ekonomi"], b:"Belgrad Antlaşması — Belgrad, Semendire ve kuzey Sırbistan'ın geri alınışı", gun:"18 Eylül 1739", yer:"Belgrad", yer_id:"Belgrad", kisiler:"I. Mahmud, İvaz Mehmed Paşa",
  d:"Avusturya ve Rusya'ya karşı iki cephede yürütülen savaşın (1736–1739) sonunda Belgrad ve Kuzey Sırbistan geri alındı; Rusya Azak'ı silahsızlandırmayı ve Karadeniz'de donanma bulundurmamayı kabul etti. 18. yüzyıl Osmanlı diplomasisinin ve ordusunun son büyük başarısı sayılan antlaşma, imparatorluğa çeyrek yüzyıllık bir barış dönemi kazandırdı.", kaynak:"belgrad-antlasmalari", duygu:["🤝"] },
{ t:"1770-07", k:"savas", etiket:["savas"], b:"Çeşme baskını", gun:"6–7 Temmuz 1770", yer:"Çeşme limanı, İzmir", kisiler:"Aleksey Orlov, Hasan Paşa (Cezayirli)",
  d:"Baltık'tan yola çıkıp Cebelitarık üzerinden Akdeniz'e giren Rus filosu, Osmanlı donanmasını sığındığı Çeşme limanında ateş gemileriyle basarak neredeyse tamamen yaktı. Rusya ilk kez Akdeniz'de büyük deniz gücü olarak belirdi; felaket, 1774 Küçük Kaynarca'ya giden savaşın kaderini belirleyen darbelerden biri oldu ve donanmanın köklü ıslahı ihtiyacını gözler önüne serdi.", kaynak:"cesme-vakasi" },
{ t:"1774-07-21", k:"antlasma", etiket:["antlasma","diplomasi","toprak-kazanc","ekonomi"], b:"Küçük Kaynarca Antlaşması", gun:"21 Temmuz 1774", yer:"Küçük Kaynarca, Dobruca", kisiler:"I. Abdülhamid, Muhsinzâde Mehmed Paşa, II. Katerina",
  d:"1768–1774 savaşını bitiren ve Osmanlı tarihinin en ağır antlaşmalarından sayılan Küçük Kaynarca'yla Kırım Hanlığı'na 'bağımsızlık' verildi — fiilen Rus nüfuz alanı yaratılmış oldu. Rusya Karadeniz kıyısına yerleşti, ticaret gemilerine Boğazlardan geçiş hakkı ve İstanbul'da daimî elçilik kazandı; Ortodoks tebaa üzerindeki muğlak himaye kaydı, sonraki yüzyılın müdahale gerekçelerinin kapısını araladı. İlk kez halkı Müslüman bir toprak Osmanlı hâkimiyetinden çıkarılıyordu.", kaynak:"kucuk-kaynarca-antlasmasi", duygu:["🤝"] },
{ t:"1783-04-19", k:"kayip", etiket:["toprak-kaybi","toprak-kazanc"], b:"Kırım'ın Rusya'ya ilhakı", gun:"8/19 Nisan 1783", yer:"Kırım", kisiler:"II. Katerina, Şahin Giray",
  d:"Küçük Kaynarca'nın yarattığı 'bağımsız' Kırım, son han Şahin Giray dönemindeki karışıklıklar bahane edilerek II. Katerina'nın manifestosuyla Rusya'ya ilhak edildi. Üç asırlık Osmanlı-Kırım ortaklığı sona erdi; kuzey steplerinin kaybı İstanbul'un savunma derinliğini ortadan kaldırdı ve on binlerce Kırım Tatarı'nın Osmanlı topraklarına göçünün ilk büyük dalgasını başlattı.", kaynak:"kirim-hanligi", duygu:["😔"] },
{ t:"1789-04", k:"reform", etiket:["siyaset","diplomasi"], b:"III. Selim ve Nizâm-ı Cedîd", gun:"7 Nisan 1789", yer:"İstanbul", yer_id:"İstanbul", kisiler:"III. Selim",
  d:"Savaşın ortasında tahta çıkan III. Selim, yenilgilerin yapısal olduğunu görerek 'Nizâm-ı Cedîd' (Yeni Düzen) adıyla kapsamlı bir ıslahat programı başlattı: Avrupa usulünde talimli yeni bir ordu, bunu finanse eden ayrı hazine (Îrâd-ı Cedîd), mühendishanelerin güçlendirilmesi ve Avrupa başkentlerinde ilk daimî elçilikler. Program, modern Türk reform geleneğinin başlangıcı kabul edilir; ancak ocaklar ve âyanların direnciyle 1807'de yıkılacaktı.", kaynak:"nizam-i-cedid" },
{ t:"1798-06-12", k:"savas", etiket:["savas"], b:"Malta şövalyelerinin tasfiyesi — Fransız donanmasının yoldaki durağı", gun:"12 Haziran 1798 (TDV yalnız yılı veriyor)", yer:"Malta", yer_id:"Malta", kisiler:"Napolyon Bonapart, Ferdinand von Hompesch",
  d:"Mısır'a giden Fransız donanması yolu üzerindeki Malta'ya uğradı; St. Jean (Malta) şövalyeleri fazla direnmeden adayı teslim etti. Rodos'tan 1522'de sürülüp buraya yerleşen şövalye tarikatının son kalesi böylece sona erdi. Malta iki yıl sonra İngiltere'nin eline geçecek, Napolyon ise adadan doğrudan İskenderiye'ye yönelecekti.", kaynak:"malta", duygu:["⚔️"] },
{ t:"1798-07-01", k:"savas", etiket:["savas","toprak-kazanc"], b:"Napolyon'un Mısır'ı işgali", gun:"1 Temmuz 1798 (İskenderiye'ye çıkış)", yer:"Mısır", kisiler:"Napolyon Bonapart, Cezzâr Ahmed Paşa, Nelson",
  d:"General Bonapart'ın ordusu İskenderiye'ye çıkarak Mısır'ı işgal etti; İngiltere'nin Hindistan yolunu hedefleyen bu sefer, bir Avrupa gücünün Osmanlı'nın merkez topraklarına ilk doğrudan saldırısıydı. Nelson'ın Ebûkır baskını ve Cezzâr Ahmed Paşa'nın Akkâ savunması Fransız yürüyüşünü kırdı; işgal 1801'de sona erdi, ama bıraktığı boşlukta Kavalalı Mehmed Ali Paşa'nın yükselişi ve 'Doğu Sorunu' çağı başladı.", kaynak:"misir", duygu:["⚔️"] },
// hatalar 5.docx madde 3 — SİLİNDİ (1807-05): mükerrer: olaylar_ek7.js 1807-05-25 kaydı tam günü taşıyor
{ t:"1808-10-07", k:"antlasma", etiket:["antlasma","diplomasi","ittifak","kultur-sanat"], b:"Sened-i İttifak", gun:"29 Eylül 1808", yer:"İstanbul, Kâğıthane", kisiler:"II. Mahmud, Alemdar Mustafa Paşa, âyanlar",
  d:"II. Mahmud'u tahta çıkaran Rusçuk âyanı Alemdar Mustafa Paşa'nın öncülüğünde, saray ile taşradaki güçlü âyan aileleri arasında imzalanan belge; âyanlar padişaha bağlılık ve asker desteği taahhüt ederken, devlet de onların varlık ve haklarını tanıdı. Padişah otoritesinin bir belgeyle sınırlanmasının Osmanlı tarihindeki ilk örneği olduğundan, kimi tarihçilerce anayasal geleneğin uzak başlangıcı sayılır; fiilen birkaç ay içinde etkisiz kaldı.", kaynak:"sened-i-ittifak", duygu:["🤝"] },
{ t:"1821-03-25", k:"isyan", etiket:["ayaklanma","toprak-kazanc"], b:"Yunan İsyanı başladı", gun:"Mart 1821", yer:"Mora ve Eflak", kisiler:"Aleksandros İpsilantis, Tepedelenli Ali Paşa (dolaylı)",
  d:"Filiki Eterya örgütünün hazırladığı ayaklanma önce Eflak'ta, ardından asıl gücüyle Mora'da patlak verdi; Tepedelenli Ali Paşa gailesiyle meşgul olan devlet ilk müdahalede gecikti. İsyan, Avrupa kamuoyundaki yoğun Yunan sempatisi (filhelenizm) sayesinde kısa sürede uluslararası bir davaya dönüştü; milliyetçilik çağının Osmanlı topraklarındaki ilk başarılı bağımsızlık hareketinin fitili böyle ateşlendi. Aynı tarihte elden çıkan diğer yerleşimler: Atina, Balyabadra (Patras), İstefe (Tebai), Livadya.", kaynak:"mora", duygu:["✊"] },
{ t:"1826-06", k:"reform", etiket:["siyaset"], b:"Vak'a-i Hayriyye — Yeniçeri Ocağı kaldırıldı", gun:"15 Haziran 1826", yer:"İstanbul, Etmeydanı", kisiler:"II. Mahmud",
  d:"Yeni kurulan Eşkinci Ocağı talimlerine karşı kazan kaldıran yeniçeriler, II. Mahmud'un önceden hazırladığı sadık birliklerin top ateşiyle Etmeydanı'ndaki kışlalarında imha edildi; ocak, bütün şubeleri ve bağlı Bektaşî tekkeleriyle birlikte lağvedildi. 'Hayırlı olay' anlamındaki adıyla tarihe geçen bu operasyon, dört asırlık kurumu tasfiye ederek Asâkir-i Mansûre-i Muhammediyye ordusunun ve sonraki bütün merkezîleşme reformlarının önünü açtı.", kaynak:"vaka-i-hayriyye" },
{ t:"1827-10", k:"savas", etiket:["savas","ayaklanma","toprak-kaybi","diplomasi"], b:"Navarin baskını", gun:"20 Ekim 1827", yer:"Navarin limanı, Mora", kisiler:"Kodrington, İbrâhim Paşa (Kavalalı)",
  d:"Yunan isyanını bastırmakta olan Osmanlı-Mısır donanması, savaş ilanı olmaksızın limana giren İngiliz-Fransız-Rus birleşik filosu tarafından Navarin'de yakıldı; altmışa yakın gemi ve binlerce denizci kaybedildi. Avrupa diplomasisinde 'talihsiz olay' diye geçiştirilen baskın, Yunan bağımsızlığını fiilen garanti altına aldı ve 1828–29 Osmanlı-Rus savaşının yolunu açtı.", kaynak:"navarin" },
{ t:"1830-02", k:"kayip", etiket:["toprak-kaybi","antlasma","ekonomi"], b:"Yunanistan'ın bağımsızlığı — Cezayir'in işgali", gun:"3 Şubat 1830 (Londra Protokolü)", yer:"Londra / Cezayir", kisiler:"II. Mahmud",
  d:"Londra Protokolü'yle üç büyük devlet bağımsız bir Yunanistan Krallığı'nı tanıdı; Osmanlı Devleti 1829 Edirne Antlaşması'nın ardından bu sonucu kabullenmek zorunda kaldı. Milliyetçilik çağında imparatorluktan kopan bu ilk bağımsız devleti, aynı yılın yazında Fransa'nın Cezayir'i işgali izledi: üç yüz yıllık Osmanlı ocağı, Kuzey Afrika'daki Avrupa sömürgeciliğinin ilk büyük parçası olarak elden çıktı.", kaynak:"yunanistan" },
// hatalar 5.docx madde 3: gün zaten biliniyordu (bkz. gun: alanı), t: ay
// hassasiyetindeydi ve CLAUDE.md §8 gereği ayın 1ine genişliyordu. Tanzimat Fermanı 3 Kasım 1839.
{ t:"1839-11-03", k:"reform", etiket:["siyaset","kultur-sanat","ekonomi"], b:"Tanzimat Fermanı", gun:"3 Kasım 1839", yer:"İstanbul, Gülhane", kisiler:"Abdülmecid, Mustafa Reşid Paşa",
  d:"Gülhane'de okunan Hatt-ı Hümâyun ile din ayrımı gözetmeksizin bütün tebaanın can, mal ve namus güvenliği devlet güvencesine alındı; vergide adalet, askerlikte düzen ve yargılamasız ceza verilmemesi ilkeleri ilan edildi. Mustafa Reşid Paşa'nın eseri olan ferman, Osmanlı modernleşmesinin anayasal nitelikli ilk büyük belgesi kabul edilir ve 'Tanzimat Devri' (1839–1876) reform çağına adını vermiştir; yönetim, hukuk, eğitim ve maliyede köklü yeniden yapılanma bu çerçevede yürütüldü.", kaynak:"tanzimat", duygu:["📜"] },
{ t:"1853-10", k:"savas", etiket:["savas","ittifak","antlasma","ekonomi"], b:"Kırım Savaşı başladı", gun:"4 Ekim 1853 (savaş ilanı)", yer:"Tuna, Kafkas ve Kırım cepheleri", kisiler:"Abdülmecid, Çar I. Nikolay, Ömer Paşa",
  d:"Kutsal yerler meselesi ve Rusya'nın Ortodoks tebaa üzerinde himaye iddiasıyla başlayan kriz, Osmanlı'nın savaş ilanıyla açık çatışmaya dönüştü; Sinop baskınının ardından İngiltere ve Fransa (sonra Piyemonte) Osmanlı safında savaşa girdi. Müttefik ordularının Kırım'a çıkarak Sivastopol'ü almasıyla savaş 1856 Paris Antlaşması'yla kazanıldı; ancak savaş yıllarında alınan ilk dış borç (1854), imparatorluğu yarım yüzyıl sürecek mali bağımlılık sarmalına soktu.", kaynak:"kirim-savasi" },
{ t:"1856-02-18", k:"reform", etiket:["siyaset","antlasma","toprak-kazanc"], b:"Islahat Fermanı", gun:"18 Şubat 1856", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Abdülmecid, Âlî Paşa, Fuad Paşa",
  d:"Paris barış görüşmeleri öncesinde ilan edilen ferman, Tanzimat ilkelerini genişleterek gayrimüslim tebaaya devlet memurluğu, askerlik ve okul açma dahil geniş eşitlik hakları tanıdı; cemaat örgütlenmeleri yeniden düzenlendi. Ardından imzalanan Paris Antlaşması'yla Osmanlı Devleti resmen Avrupa devletler hukuku ailesine kabul edildi ve toprak bütünlüğü büyük devletlerin ortak garantisine alındı — bu garanti, uygulamada müdahalelerin yeni kapısı olacaktı.", kaynak:"islahat-fermani", duygu:["📜"] },
// hatalar 5.docx madde 3: gün zaten biliniyordu (bkz. gun: alanı), t: ay
// hassasiyetindeydi ve CLAUDE.md §8 gereği ayın 1ine genişliyordu. Kanûn-ı Esâsî 23 Aralık 1876.
{ t:"1876-12-23", k:"reform", etiket:["siyaset","kultur-sanat"], b:"Kanûn-ı Esâsî — I. Meşrutiyet", gun:"23 Aralık 1876", yer:"İstanbul", yer_id:"İstanbul", kisiler:"II. Abdülhamid, Midhat Paşa",
  d:"Balkan bunalımını görüşmek üzere İstanbul'da toplanan uluslararası konferansın açıldığı gün, top atışlarıyla ilk Osmanlı anayasası ilan edildi; Midhat Paşa öncülüğündeki 'Yeni Osmanlılar' hareketinin eseri olan Kanûn-ı Esâsî ile iki meclisli parlamento kuruldu. Meclis-i Meb'ûsan Mart 1877'de açıldı; ancak II. Abdülhamid, 93 Harbi'ni gerekçe göstererek Şubat 1878'de meclisi süresiz tatil etti ve anayasa otuz yıl askıda kaldı.", kaynak:"kanun-i-esasi", duygu:["📜"] },
{ t:"1877-04", k:"savas", etiket:["savas","ekonomi"], b:"93 Harbi (1877–78 Osmanlı-Rus Savaşı)", gun:"24 Nisan 1877 (Rus savaş ilanı)", yer:"Tuna ve Kafkas cepheleri", kisiler:"Gazi Osman Paşa, Ahmed Muhtar Paşa, Grandük Nikolay",
  d:"Rûmî 1293 yılına denk geldiği için '93 Harbi' diye anılan savaşta Rus orduları iki cepheden saldırdı; Gazi Osman Paşa'nın Plevne savunması ve Ahmed Muhtar Paşa'nın Kafkas muharebeleri destanlaştıysa da cephe çöktü ve Ruslar Yeşilköy'e (Ayastefanos) kadar ilerledi. Savaş, Balkanlar ve Kafkasya'dan İstanbul'a yönelen, etkileri bugüne uzanan büyük Müslüman göç dalgalarını başlattı; imparatorluğun demografik ve mali yapısı bir daha eski hâline dönemedi.", kaynak:"doksanuc-harbi" },
{ t:"1878-07-13", k:"antlasma", etiket:["antlasma","diplomasi"], b:"Berlin Antlaşması", gun:"13 Temmuz 1878", yer:"Berlin", yer_id:"Berlin", kisiler:"II. Abdülhamid, Bismarck, Karatodori Paşa",
  d:"Ayastefanos'un yarattığı 'Büyük Bulgaristan'ı büyük devletler dengesi adına revize eden Berlin Kongresi, yine de ağır bir tablo bıraktı: Sırbistan, Karadağ ve Romanya bağımsız oldu; özerk Bulgaristan Prensliği kuruldu; Bosna-Hersek Avusturya işgaline, Kıbrıs İngiliz idaresine, Kars-Ardahan-Batum Rusya'ya bırakıldı. Rumeli'deki beş yüz yıllık Osmanlı düzeni büyük ölçüde çözüldü; 'şark meselesi' Avrupa diplomasisinin sürekli gündemi hâline geldi. Aynı tarihte elden çıkan diğer yerleşimler: Filibe, Vidin, Tırnova, Varna, Şumnu, Silistre, Rusçuk, Bükreş, Yaş, Köstence.", statu_vasal:["Eski Zağra (Stara Zagora)","Tatarpazarcığı","Filibe","Vidin","Tırnova","Varna","Şumnu","Silistre","Rusçuk"], kaynak:"berlin-antlasmasi", duygu:["🤝"] },
{ t:"1881-05-12", k:"kayip", etiket:["toprak-kaybi","antlasma"], b:"Tunus'un işgali ve Düyûn-ı Umûmiyye", gun:"12 Mayıs 1881 (Bardo Antlaşması)", yer:"Tunus / İstanbul", kisiler:"II. Abdülhamid",
  d:"Fransa, Cezayir sınırındaki olayları bahane ederek Tunus'u işgal etti ve Bardo Antlaşması'yla himayesine aldı; Osmanlı'nın Kuzey Afrika'daki varlığı Trablusgarp'a indi. Aynı yıl çıkarılan Muharrem Kararnamesi'yle iflas etmiş dış borçların yönetimi için alacaklıların temsil edildiği Düyûn-ı Umûmiyye İdaresi kuruldu: tuz, tütün, ipek gibi temel gelirler doğrudan bu yabancı idareye bağlandı ve mali egemenlik ağır biçimde sınırlandı. Aynı tarihte elden çıkan diğer yerleşimler: Kayrevan, Gabes, Sfaks, Cerbe (Djerba).", kaynak:"duyun-i-umumiyye", duygu:["😔"] },
{ t:"1882-09", k:"kayip", etiket:["toprak-kaybi","ekonomi"], b:"Mısır'ın İngiliz işgali", gun:"Eylül 1882 (Tel el-Kebîr ve Kahire)", yer:"Mısır", kisiler:"Urâbî Paşa, General Wolseley",
  d:"Mısır'da mali iflas ve yabancı denetimine karşı yükselen Urâbî Paşa hareketi, İskenderiye'nin bombalanmasının ardından karaya çıkan İngiliz ordusunun Tel el-Kebîr zaferiyle ezildi ve Kahire işgal edildi. Mısır hukuken Osmanlı'ya bağlı kalmayı sürdürdüyse de fiilen İngiliz yönetimine girdi; Süveyş Kanalı'nın denetimi, Britanya imparatorluk stratejisinin merkezine yerleşti.", kaynak:"misir" },
{ t:"1908-07-23", k:"reform", etiket:["siyaset","toprak-kazanc"], b:"II. Meşrutiyet'in ilanı", gun:"23 Temmuz 1908", yer:"Manastır, Selanik, İstanbul", kisiler:"II. Abdülhamid, Enver Bey, Niyazi Bey",
  d:"İttihat ve Terakki Cemiyeti'ne bağlı subayların Makedonya'da dağa çıkmasıyla büyüyen hareket karşısında II. Abdülhamid, Kanûn-ı Esâsî'yi yeniden yürürlüğe koydu; 'hürriyetin ilanı' coşkuyla karşılandı ve seçimlere gidildi. Ancak istikrar gelmedi: 31 Mart Vak'ası (Nisan 1909) bastırıldıktan sonra Abdülhamid tahttan indirildi; Bulgaristan'ın bağımsızlığı, Bosna'nın ilhakı ve Girit'in Yunanistan'a yönelmesi de bu çalkantılı aylarda gerçekleşti.", kaynak:"mesrutiyet", duygu:["📜"] },
{ t:"1911-09", k:"savas", etiket:["savas","antlasma"], b:"Trablusgarp Savaşı", gun:"29 Eylül 1911 (İtalyan savaş ilanı)", yer:"Trablusgarp ve Bingazi", kisiler:"Mustafa Kemal, Enver Bey, Şeyh Senûsî aileleri",
  d:"Sömürge arayışındaki İtalya, Osmanlı'nın Kuzey Afrika'daki son toprağı Trablusgarp'a savaş ilan edip kıyıları işgal etti; donanması olmayan devlet düzenli ordu gönderemeyince Mustafa Kemal ve Enver Bey gibi genç subaylar gizlice bölgeye geçerek Senûsî kabileleriyle etkili bir direniş örgütledi. Balkan Savaşı'nın patlaması üzerine imzalanan Uşi Antlaşması'yla (18 Ekim 1912) Libya İtalya'ya bırakıldı; İtalya ayrıca Rodos ve Oniki Ada'yı işgal etti.", kaynak:"trablusgarp-savasi" },
{ t:"1912-10", k:"savas", etiket:["savas","ittifak","toprak-kaybi"], b:"Balkan Savaşları başladı", gun:"8 Ekim 1912 (Karadağ'ın savaş ilanı)", yer:"Rumeli", kisiler:"Nâzım Paşa, Balkan ittifakı",
  d:"Karadağ'ın savaş ilanını Bulgaristan, Sırbistan ve Yunanistan izledi; seferberliğini tamamlayamayan ve siyasî çekişmelerle bölünmüş Osmanlı ordusu birkaç hafta içinde Rumeli'yi kaybetti, ordu Çatalca hattına çekildi ve yüz binlerce muhacir İstanbul'a aktı. Müttefiklerin ganimet kavgasına dönüşen II. Balkan Savaşı'nda (Temmuz 1913) Edirne ve Doğu Trakya geri alındı; ama beş asırlık Rumeli, birkaç ayda elden çıkmıştı.", kaynak:"balkan-savaslari" },
{ t:"1913-05-30", k:"kayip", etiket:["toprak-kaybi","antlasma","toprak-kazanc","ekonomi"], b:"Londra Antlaşması — Rumeli'nin kaybı", gun:"30 Mayıs 1913", yer:"Londra", yer_id:"Londra", kisiler:"Balkan devletleri temsilcileri",
  d:"I. Balkan Savaşı'nı bitiren Londra Antlaşması'yla Midye-Enez hattının batısındaki bütün topraklar ve Ege adaları kaybedildi; Arnavutluk bağımsız oldu. Beş yüz yılı aşkın süredir imparatorluğun demografik, iktisadî ve kültürel ağırlık merkezi olan Rumeli'den geriye yalnızca Doğu Trakya kalacaktı (Edirne, II. Balkan Savaşı'nda geri alındı); kayıp, İttihatçı yönetimin savaş ve iskân siyasetini köklü biçimde sertleştirdi.", kaynak:"balkan-savaslari", duygu:["😔"] },
{ t:"1914-11", k:"savas", etiket:["savas","ekonomi"], b:"I. Dünya Savaşı'na giriş", gun:"29 Ekim – 11 Kasım 1914", yer:"Karadeniz / İstanbul", kisiler:"Enver Paşa, Amiral Souchon",
  d:"İngiltere'den kaçan Goeben ve Breslau zırhlılarının satın alınmış gösterilerek Boğaz'dan içeri alınması, devleti adım adım Almanya'nın yanına çekti; Amiral Souchon komutasındaki donanmanın Rus limanlarını bombalamasıyla (29 Ekim) savaş fiilen başladı ve karşılıklı ilanlar Kasım başında geldi. Cihâd-ı Ekber ilanına rağmen beklenen etki doğmadı; imparatorluk, dört yıl boyunca Kafkasya'dan Filistin'e beş ayrı cephede varlık savaşına girdi.", kaynak:"birinci-dunya-savasi" },
{ t:"1915-03", k:"savas", etiket:["savas","ittifak"], b:"Çanakkale Zaferi", gun:"18 Mart 1915 (deniz zaferi)", yer:"Çanakkale Boğazı ve Gelibolu", kisiler:"Mustafa Kemal, Cevat Paşa, Seyit Onbaşı, Liman von Sanders",
  d:"İstanbul'u düşürüp Rusya'ya ulaşmayı hedefleyen müttefik armadası, 18 Mart'ta mayın hatları ve tabyaların ateşiyle Boğaz'dan geri püskürtüldü; Nusret mayın gemisinin döşediği hat savaşın kaderini belirledi. Nisan'da başlayan Gelibolu kara harekâtı da Anafartalar ve Conkbayırı'nda durduruldu; müttefikler Ocak 1916'da yarımadayı tamamen boşalttı. Yarbay Mustafa Kemal'in adı bu cephede duyuldu; yaklaşık çeyrek milyon şehit ve kayıpla kazanılan zafer, Millî Mücadele kadrolarının ve ruhunun doğduğu yer kabul edilir.", kaynak:"canakkale-muharebeleri" },
{ t:"1916-06-10", k:"isyan", etiket:["ayaklanma"], b:"Şerif Hüseyin isyanı", gun:"Haziran 1916", yer:"Mekke ve Hicaz", kisiler:"Şerif Hüseyin, Fahreddin Paşa, T.E. Lawrence",
  d:"Mekke Emiri Şerif Hüseyin, İngilizlerle yürüttüğü gizli yazışmaların ardından bağımsız Arap krallığı vaadiyle ayaklandı; Hicaz demiryolu akınlara hedef oldu. Fahreddin Paşa'nın Medine'yi mütarekeden sonrasına dek süren efsanevî savunması direnişin simgesi olarak kaldıysa da isyan, Filistin cephesindeki İngiliz ilerleyişiyle birleşerek Arap vilayetlerindeki Osmanlı hâkimiyetinin çözülüşünü hızlandırdı. Aynı tarihte elden çıkan diğer yerleşimler: Tâif.", kaynak:"hasimiler", duygu:["✊"] },
{ t:"1918-10-30", k:"antlasma", etiket:["antlasma","diplomasi","ekonomi"], b:"Mondros Mütarekesi", gun:"30 Ekim 1918", yer:"Limni adası, Mondros limanı", kisiler:"Rauf Bey (Orbay), Amiral Calthorpe",
  d:"Bulgaristan'ın çöküşüyle cepheleri birbirinden kopan Osmanlı Devleti, Agamemnon zırhlısında imzalanan mütarekeyle savaştan çekildi. Boğazların açılması ve özellikle güvenliği tehdit edilen yerlerin işgal edilebilmesine imkân veren 7. madde, kısa sürede fiilî paylaşımın hukuki kılıfı yapıldı: Musul, İskenderun, ardından İzmir ve İstanbul işgal edildi. Mütareke, imparatorluğun fiilî sonunun belgesi kabul edilir. Aynı tarihte elden çıkan diğer yerleşimler: Hama, Şam, Humus.", kaynak:"mondros-mutarekesi", duygu:["🤝"] },
{ t:"1919-05", k:"diger", etiket:["diger"], b:"Mustafa Kemal Samsun'da — Millî Mücadele", gun:"19 Mayıs 1919", yer:"Samsun", yer_id:"Samsun", kisiler:"Mustafa Kemal Paşa",
  d:"İzmir'in işgalinin yarattığı infial ortamında, 9. Ordu müfettişi sıfatıyla Samsun'a çıkan Mustafa Kemal Paşa, resmî görevini Anadolu'daki direnişi örgütlemeye çevirdi. Amasya Genelgesi ile Erzurum ve Sivas kongreleri bu çıkışın devamıdır; 'milletin bağımsızlığını yine milletin azim ve kararı kurtaracaktır' ilkesi, Millî Mücadele'nin siyasal programının çekirdeği oldu.", kaynak:"milli-mucadele" },
{ t:"1920-04", k:"diger", etiket:["antlasma"], b:"TBMM'nin açılışı ve Sevr", gun:"23 Nisan / 10 Ağustos 1920", yer:"Ankara / Sevr", kisiler:"Mustafa Kemal Paşa, Damad Ferid Paşa",
  d:"İstanbul'un resmen işgali ve Meclis-i Meb'ûsan'ın dağıtılması üzerine 23 Nisan 1920'de Ankara'da Büyük Millet Meclisi açıldı; olağanüstü yetkileri kendinde toplayan meclis, millî iradeye dayalı yeni devletin çekirdeği oldu. Ağustos'ta İstanbul hükümetinin imzaladığı Sevr Antlaşması Anadolu'yu paylaştırıyordu; TBMM antlaşmayı imzalayanları vatan haini ilan etti ve Sevr hiçbir zaman uygulanamadı.", kaynak:"sevr-antlasmasi" },
{ t:"1921-09", k:"savas", etiket:["savas"], b:"Sakarya Meydan Muharebesi", gun:"23 Ağustos – 13 Eylül 1921", yer:"Sakarya nehri doğusu, Ankara önleri", kisiler:"Mustafa Kemal Paşa, Fevzi Paşa, İsmet Paşa",
  d:"Ankara'ya 50 kilometreye kadar yaklaşan Yunan taarruzu, başkomutanlık yetkisini üstlenen Mustafa Kemal Paşa'nın 'hattı müdafaa yoktur, sathı müdafaa vardır' emriyle yürütülen 22 gün 22 gecelik muharebede kırıldı. Yunan ordusu ilk kez stratejik savunmaya geçti; zafer Mustafa Kemal'e gazilik ve müşirlik (mareşallik) getirdi, Fransa ile Ankara İtilâfnâmesi'nin ve dış tanınmanın kapısını açtı.", kaynak:"sakarya-meydan-muharebesi" },
{ t:"1922-09-09", k:"savas", etiket:["savas"], b:"Büyük Taarruz ve İzmir'in kurtuluşu", gun:"26 Ağustos – 9 Eylül 1922", yer:"Afyon, Dumlupınar, İzmir", kisiler:"Mustafa Kemal Paşa, Fevzi Çakmak, Trikupis",
  d:"26 Ağustos sabahı Kocatepe'den başlatılan taarruz, 30 Ağustos'ta Dumlupınar'da Başkomutan Meydan Muharebesi'yle Yunan ana kuvvetlerinin imhasına ulaştı; 'Ordular, ilk hedefiniz Akdeniz'dir, ileri!' emriyle süren takiple 9 Eylül'de İzmir kurtarıldı. Mudanya Mütarekesi'yle (11 Ekim) Doğu Trakya savaşsız geri alındı; askerî zafer, Lozan'da kurulacak yeni devletin masadaki gücünü belirledi.", kaynak:"buyuk-taarruz", duygu:["⚔️"] },
{ t:"1922-11-01", k:"taht", etiket:["siyaset"], b:"Saltanatın kaldırılması", gun:"1 Kasım 1922", yer:"Ankara / İstanbul", kisiler:"TBMM, VI. Mehmed Vahideddin, Abdülmecid Efendi",
  d:"Lozan görüşmelerine İstanbul hükümetinin de çağrılması üzerine TBMM, 1 Kasım 1922'de saltanat ile hilâfeti ayırarak saltanatı kaldırdı; 623 yıllık Osmanlı hanedan yönetimi hukuken sona erdi. VI. Mehmed Vahideddin 17 Kasım'da bir İngiliz zırhlısıyla ülkeden ayrıldı; hilâfet makamına TBMM kararıyla Abdülmecid Efendi getirildi ve bu makam da 3 Mart 1924'te kaldırılacaktı.", kaynak:"saltanat", duygu:["👑"] },
{ t:"1923-07-24", k:"antlasma", etiket:["antlasma","diplomasi"], b:"Lozan Antlaşması", gun:"24 Temmuz 1923", yer:"Lozan, İsviçre", kisiler:"İsmet Paşa (İnönü), Rıza Nur, Lord Curzon",
  d:"Sekiz ay süren çetin müzakerelerin sonunda imzalanan Lozan Barış Antlaşması'yla yeni Türk devletinin sınırları, tam bağımsızlığı ve egemenliği uluslararası alanda tanındı; kapitülasyonlar kaldırıldı, Düyûn-ı Umûmiyye tasfiye sürecine sokuldu, nüfus mübadelesi düzenlendi. Sevr'i fiilen hükümsüz kılan Lozan, Millî Mücadele'nin diplomatik zaferi ve Cumhuriyet'in kurucu dış belgesi kabul edilir.", kaynak:"lozan-antlasmasi", duygu:["🤝"] },
{ t:"1923-10", k:"kurulus", etiket:["siyaset","ekonomi"], b:"Cumhuriyet'in ilanı", gun:"29 Ekim 1923", yer:"Ankara", yer_id:"Ankara", kisiler:"Mustafa Kemal Atatürk, İsmet İnönü",
  d:"TBMM'nin anayasa değişikliğiyle 'Türkiye Devleti'nin hükûmet şekli cumhuriyettir' hükmünü kabul etmesiyle Cumhuriyet ilan edildi; Mustafa Kemal Paşa ilk cumhurbaşkanı seçildi. 1299'da bir uç beyliği olarak başlayan 624 yıllık Osmanlı serüveni böylece kapanmış, egemenliğin kayıtsız şartsız millete ait olduğu yeni devlet, imparatorluğun mirası üzerinde kurulmuştur.", kaynak:"cumhuriyet" }
];
